INSERT INTO public_itineraries (id, data, created_by, updated_at) VALUES
('bali-6gg', '{"id":"bali-6gg","title":"Bali: templi e spiagge","country":"Indonesia","continent":"Asia","coverUrl":"https://images.unsplash.com/photo-1537996194471-e657df975ab4?w=800&q=80","description":"L'\''isola degli dèi: templi sospesi, terrazze di riso, surf e spiagge paradisiache in un itinerario di 6 giorni.","duration":6,"difficulty":"facile","budget":"basso","bestPeriod":"Aprile-Ottobre (stagione secca)","transport":"Scooter, transfer privato, taxi","tips":"Il scooter è il mezzo migliore ma servono patenti internazionali. Copriti le spalle ai templi. Evita Kuta se cercate relax.","days":{"2025-07-01":{"place":"Ubud","activities":["Arrivo","Tegallalang Rice Terraces","Ubud Monkey Forest"],"accommodation":"Villa a Ubud","categories":["natura","cultura"],"image":"https://images.unsplash.com/photo-1537996194471-e657df975ab4?w=800&q=80"},"2025-07-02":{"place":"Ubud","activities":["Tirta Empul Temple","Tegenungan Waterfall","Cooking class balinese"],"accommodation":"Villa a Ubud","categories":["cultura","natura","cibo"],"image":"https://images.unsplash.com/photo-1555400038-63f5ba517a47?w=800&q=80"},"2025-07-03":{"place":"Nusa Penida","activities":["Traghetto a Nusa Penida","Kelingking Beach","Angel'\''s Billabong"],"accommodation":"Guesthouse a Nusa Penida","categories":["natura","avventura"],"image":"https://images.unsplash.com/photo-1518548419970-58e3b4079ab2?w=800&q=80"},"2025-07-04":{"place":"Nusa Penida / Seminyak","activities":["Snorkeling con manta ray","Rientro a Bali","Seminyak beach"],"accommodation":"Hotel a Seminyak","categories":["avventura","relax"],"image":"https://images.unsplash.com/photo-1537996194471-e657df975ab4?w=800&q=80"},"2025-07-05":{"place":"Uluwatu","activities":["Uluwatu Temple","Kecak fire dance","Jimbaran seafood dinner"],"accommodation":"Hotel a Seminyak","categories":["cultura","cibo"],"image":"https://images.unsplash.com/photo-1555400038-63f5ba517a47?w=800&q=80"},"2025-07-06":{"place":"Seminyak","activities":["Yoga al tramonto","Beach club","Partenza"],"accommodation":"","categories":["relax","benessere"],"image":"https://images.unsplash.com/photo-1518548419970-58e3b4079ab2?w=800&q=80"}},"extras":[]}', 'system', now()),
('roma-5gg', '{"id":"roma-5gg","title":"Roma in 5 giorni","country":"Italia","continent":"Europa","coverUrl":"https://images.unsplash.com/photo-1552832230-c0197dd311b5?w=800&q=80","description":"Scopri la Città Eterna: dai monumenti antichi ai quartieri più autentici, un itinerario completo per vivere Roma come un locale.","duration":5,"difficulty":"facile","budget":"medio","bestPeriod":"Aprile-Giugno, Settembre-Ottobre","transport":"A piedi, metro, bus","tips":"Prenota i musei Vaticani con almeno 2 settimane di anticipo. La domenica i musei statali sono gratuiti ma molto affollati.","days":{"2025-04-07":{"place":"Roma","activities":["Colosseo e Fori Imperiali","Palatino","Piazza Venezia"],"accommodation":"Hotel nel rione Monti","categories":["cultura","storia"],"image":"https://images.unsplash.com/photo-1555992828-ca4dbe41d294?w=800&q=80"},"2025-04-08":{"place":"Roma","activities":["Vaticano e Cappella Sistina","Basilica di San Pietro","Castel Sant'\''Angelo"],"accommodation":"Hotel nel rione Monti","categories":["cultura","arte"],"image":"https://images.unsplash.com/photo-1541410854169-52e4a28998c0?w=800&q=80"},"2025-04-09":{"place":"Roma","activities":["Pantheon","Piazza Navona","Fontana di Trevi","Spagna"],"accommodation":"Hotel nel rione Monti","categories":["cultura","passeggiata"],"image":"https://images.unsplash.com/photo-1531572753322-ad063cecc140?w=800&q=80"},"2025-04-10":{"place":"Roma","activities":["Trastevere","Villa Borghese","Pincio al tramonto"],"accommodation":"Hotel nel rione Monti","categories":["natura","cibo"],"image":"https://images.unsplash.com/photo-1516483638261-f4dbaf036963?w=800&q=80"},"2025-04-11":{"place":"Roma","activities":["Borghese (prenotazione)","Via del Corso","Aperitivo in rooftop bar"],"accommodation":"Hotel nel rione Monti","categories":["arte","shopping"],"image":"https://images.unsplash.com/photo-1504699439244-94498e4e0920?w=800&q=80"}},"extras":[]}', 'system', now()),
('kyoto-7gg', '{"id":"kyoto-7gg","title":"Kyoto e i suoi templi","country":"Giappone","continent":"Asia","coverUrl":"https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?w=800&q=80","description":"Immergiti nella cultura giapponese con un tour dei templi più iconici di Kyoto, dai giardini di zen ai santuari shintoisti.","duration":7,"difficulty":"facile","budget":"alto","bestPeriod":"Marzo-Aprile (ciliegi), Novembre (autunno)","transport":"Treno locale, autobus, bicicletta","tips":"Compra il bus pass giornaliero. Molti templi chiudono presto (16:30-17:00). Evita la bolle高峰期 di aprile e novembre.","days":{"2025-10-01":{"place":"Kyoto","activities":["Arrivo e installazione","Passeggiata a Gion","Cena kaiseki"],"accommodation":"Ryokan nel quartiere Higashiyama","categories":["cultura","cibo"],"image":"https://images.unsplash.com/photo-1478436127897-769e1b3f0f36?w=800&q=80"},"2025-10-02":{"place":"Kyoto","activities":["Kinkaku-ji (Padiglione d'\''Oro)","Ryoan-ji","Nijo Castle"],"accommodation":"Ryokan nel quartiere Higashiyama","categories":["cultura","storia"],"image":"https://images.unsplash.com/photo-1579027989536-b7b1f875659b?w=800&q=80"},"2025-10-03":{"place":"Kyoto","activities":["Fushimi Inari (mille torii)","Tofuku-ji","Sake brewery tour"],"accommodation":"Ryokan nel quartiere Higashiyama","categories":["cultura","natura"],"image":"https://images.unsplash.com/photo-1478436127897-769e1b3f0f36?w=800&q=80"},"2025-10-04":{"place":"Arashiyama","activities":["Bamboo Grove","Tenryu-ji","Monkey Park"],"accommodation":"Ryokan nel quartiere Higashiyama","categories":["natura","cultura"],"image":"https://images.unsplash.com/photo-1545569341-9eb8b30979d9?w=800&q=80"},"2025-10-05":{"place":"Kyoto","activities":["Philosopher'\''s Path","Ginkaku-ji","Nanzen-ji"],"accommodation":"Ryokan nel quartiere Higashiyama","categories":["natura","cultura"],"image":"https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?w=800&q=80"},"2025-10-06":{"place":"Kyoto","activities":["Tea ceremony","Shopping a Nishiki Market","Cena yakitori"],"accommodation":"Ryokan nel quartiere Higashiyama","categories":["cultura","cibo","shopping"],"image":"https://images.unsplash.com/photo-1528360983277-13d401cdc186?w=800&q=80"},"2025-10-07":{"place":"Kyoto","activities":["Uji (tè matcha)","Partenza"],"accommodation":"","categories":["cibo","cultura"],"image":"https://images.unsplash.com/photo-1545569341-9eb8b30979d9?w=800&q=80"}},"extras":[]}', 'system', now()),
('marrakech-4gg', '{"id":"marrakech-4gg","title":"Marrakech e l'\''Atlante","country":"Marocco","continent":"Africa","coverUrl":"https://images.unsplash.com/photo-1518730518541-d0843268c287?w=800&q=80","description":"Esplora la città rossa e la bellezza della montagna: mercati, deserto e culture berbere in un viaggio indimenticabile.","duration":4,"difficulty":"media","budget":"basso","bestPeriod":"Marzo-Maggio, Ottobre-Novembre","transport":"Taxi, transfer privato, trekking","tips":"Tratta sempre al mercato (souk). Porta scarpe comode per il trekking. I date sono freschi anche d'\''inverno.","days":{"2025-03-15":{"place":"Marrakech","activities":["Medina e souk","Jardin Majorelle","Piazza Jemaa el-Fna al tramonto"],"accommodation":"Riad nel medina","categories":["cultura","shopping"],"image":"https://images.unsplash.com/photo-1509023464722-18d996393ca8?w=800&q=80"},"2025-03-16":{"place":"Marrakech","activities":["Palazzo Bahia","Museo Yves Saint Laurent","Hammam tradizionale"],"accommodation":"Riad nel medina","categories":["cultura","benessere"],"image":"https://images.unsplash.com/photo-1518730518541-d0843268c287?w=800&q=80"},"2025-03-17":{"place":"Atlante","activities":["Transfer all'\''Atlante","Trekking nelle valli","Notte sotto le stelle"],"accommodation":"Bivouac berbero","categories":["natura","avventura"],"image":"https://images.unsplash.com/photo-1489749798305-4fea3ae63d43?w=800&q=80"},"2025-03-18":{"place":"Atlante / Marrakech","activities":["Alba sull'\''Atlante","Villaggi berberi","Rientro a Marrakech"],"accommodation":"","categories":["natura","cultura"],"image":"https://images.unsplash.com/photo-1516026672322-bc52d61a55d5?w=800&q=80"}},"extras":[]}', 'system', now()),
('new-york-5gg', '{"id":"new-york-5gg","title":"New York City immersione","country":"Stati Uniti","continent":"Americhe","coverUrl":"https://images.unsplash.com/photo-1496442226666-8d4d0e62e6e9?w=800&q=80","description":"Vivi NYC come un vero newyorkese: dai grattacieli di Manhattan ai Brooklyn, dai museum hopping ai rooftop bar.","duration":5,"difficulty":"facile","budget":"alto","bestPeriod":"Aprile-Giugno, Settembre-Novembre","transport":"Metro (MTA), taxi, piedi","tips":"Compra la MetroCard 7 giorni. Brooklyn Bridge è meglio al mattino presto. Prenota per il ferry di Staten Island (gratis).","days":{"2025-06-10":{"place":"New York","activities":["Times Square","Broadway show","Central Park"],"accommodation":"Hotel a Midtown","categories":["cultura","intrattenimento"],"image":"https://images.unsplash.com/photo-1534430480872-3498386e7856?w=800&q=80"},"2025-06-11":{"place":"New York","activities":["Statue of Liberty","Ellis Island","Wall Street","9/11 Memorial"],"accommodation":"Hotel a Midtown","categories":["storia","cultura"],"image":"https://images.unsplash.com/photo-1503891617560-5b8c2e28cbf6?w=800&q=80"},"2025-06-12":{"place":"Brooklyn","activities":["Brooklyn Bridge walk","DUMBO","Williamsburg","Bushwick street art"],"accommodation":"Hotel a Midtown","categories":["passeggiata","arte"],"image":"https://images.unsplash.com/photo-1496442226666-8d4d0e62e6e9?w=800&q=80"},"2025-06-13":{"place":"New York","activities":["Met Museum","MoMA","Fifth Avenue","Rockefeller Center"],"accommodation":"Hotel a Midtown","categories":["arte","shopping"],"image":"https://images.unsplash.com/photo-1534430480872-3498386e7856?w=800&q=80"},"2025-06-14":{"place":"New York","activities":["High Line","Chelsea Market","SoHo","Rooftop bar al tramonto"],"accommodation":"Hotel a Midtown","categories":["passeggiata","cibo"],"image":"https://images.unsplash.com/photo-1503891617560-5b8c2e28cbf6?w=800&q=80"}},"extras":[]}', 'system', now()),
('islanda-8gg', '{"id":"islanda-8gg","title":"Islanda: Ring Road","country":"Islanda","continent":"Europa","coverUrl":"https://images.unsplash.com/photo-1504829857797-ddff29c27927?w=800&q=80","description":"Il giro completo dell'\''Islanda in 8 giorni: ghiacciai, cascate, sorgenti termali e paesaggi lunar lungo la Ring Road.","duration":8,"difficulty":"media","budget":"alto","bestPeriod":"Giugno-Agosto (mecedole di luce), Settembre (aurora boreale)","transport":"Auto a noleggio (4x4 consigliato)","tips":"Prenota auto e hotel con mesi di anticipo in estate. La Ring Road è percorribile in 7 giorni ma 8 danno respiro. Porta sempre layer di vestiti.","days":{"2025-09-01":{"place":"Reykjavik","activities":["Arrivo","Blue Lagoon","Tour della città"],"accommodation":"Hotel a Reykjavik","categories":["benessere","cultura"],"image":"https://images.unsplash.com/photo-1504829857797-ddff29c27927?w=800&q=80"},"2025-09-02":{"place":"Golden Circle","activities":["Thingvellir","Geysir","Gullfoss","Friðheimar"],"accommodation":"Guesthouse vicino Selfoss","categories":["natura","cultura"],"image":"https://images.unsplash.com/photo-1520769669658-f07657f5a307?w=800&q=80"},"2025-09-03":{"place":"Sudurland","activities":["Seljalandsfoss","Skogafoss","Vik (neriere)","Reynisfjara"],"accommodation":"Guesthouse a Vik","categories":["natura","avventura"],"image":"https://images.unsplash.com/photo-1520769669658-f07657f5a307?w=800&q=80"},"2025-09-04":{"place":"Skaftafell / Jokulsarlon","activities":["Skaftafell glacier hike","Jokulsarlon glacier lagoon","Diamond Beach"],"accommodation":"Hotel vicino Jokulsarlon","categories":["avventura","natura"],"image":"https://images.unsplash.com/photo-1504829857797-ddff29c27927?w=800&q=80"},"2025-09-05":{"place":"Eastfjords","activities":["Egilsstadir","Seydisfjordur","Hengifoss"],"accommodation":"Guesthouse a Egilsstadir","categories":["natura","passeggiata"],"image":"https://images.unsplash.com/photo-1520769669658-f07657f5a307?w=800&q=80"},"2025-09-06":{"place":"Myvatn","activities":["Myvatn Nature Baths","Dimmuborgir","Godafoss","Grjotagja cave"],"accommodation":"Guesthouse a Myvatn","categories":["natura","benessere"],"image":"https://images.unsplash.com/photo-1504829857797-ddff29c27927?w=800&q=80"},"2025-09-07":{"place":"Akureyri / Westfjords","activities":["Akureyri (capitale del nord)","Snaefellsnes peninsula"],"accommodation":"Hotel a Stykkisholmur","categories":["cultura","natura"],"image":"https://images.unsplash.com/photo-1520769669658-f07657f5a307?w=800&q=80"},"2025-09-08":{"place":"Snaefellsnes / Reykjavik","activities":["Kirkjufell","Arnastapi","Rientro a Reykjavik"],"accommodation":"","categories":["natura","passeggiata"],"image":"https://images.unsplash.com/photo-1504829857797-ddff29c27927?w=800&q=80"}},"extras":[]}', 'system', now())
